// Demo: CPUFreq Governors — governor decision
var loads=[];for(var i=0;i<3;i++){loads.push((i*37+1)%100);}
var avg=loads.reduce(function(a,b){return a+b;},0)/loads.length;
var freq=avg>80?'max':avg>40?'mid':'min';
console.log('technique: CPUFreq Governors');console.log('avg load: '+avg.toFixed(0)+'% -> governor picks '+freq+' frequency');

// Demo: P-State Tables — P-state power curve
var states=[[800,5],[1600,12],[2400,25],[3200,45],[4000,75]];
console.log('technique: P-State Tables');
states.forEach(function(s){console.log(s[0]+' MHz: '+s[1]+' W');});
console.log('power rises faster than frequency — the top bin is expensive');

